#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <new>
#include <utility>
#include <vector>
#define DynamicUnionFind BaselineDUF
#include "/tmp/sirkit_four_hours_20261022/baseline/DataStructure/dynamic-union-find.cpp"
#undef DynamicUnionFind
#undef SIRKIT_DYNAMIC_UNION_FIND_DEFINED
#define DynamicUnionFind CurrentDUF
#include "/home/reinsirk/Atcoder_Env/DataStructure/dynamic-union-find.cpp"
#undef DynamicUnionFind
static int budget=-1;static std::size_t live=0,checks=0,failures=0;
[[gnu::noinline]] void* operator new(std::size_t n){if(budget==0)throw std::bad_alloc();if(budget>0)--budget;if(auto p=std::malloc(n?n:1)){++live;return p;}throw std::bad_alloc();}
[[gnu::noinline]] void* operator new[](std::size_t n){return ::operator new(n);}
[[gnu::noinline]] void release(void*p)noexcept{if(p)--live;std::free(p);}
void operator delete(void*p)noexcept{release(p);}void operator delete[](void*p)noexcept{release(p);}void operator delete(void*p,std::size_t)noexcept{release(p);}void operator delete[](void*p,std::size_t)noexcept{release(p);}
void require(bool b){++checks;if(!b)std::abort();}
const std::vector<int> keys{17,-5,std::numeric_limits<int>::max(),std::numeric_limits<int>::min(),42,-1,0,-99};
template<class U>U prepare(bool joined){U u;for(int k:keys)u.add(k);if(joined){u.unite(keys[3],keys[2]);u.unite(keys[1],keys[0]);u.unite(keys[3],keys[1]);u.unite(keys[7],keys[6]);u.unite(keys[5],keys[4]);u.unite(keys[7],keys[5]);u.unite(keys[3],keys[7]);}return u;}
void run(){
 for(bool joined:{false,true}){
  auto old=prepare<BaselineDUF>(joined);auto initial=prepare<CurrentDUF>(joined);auto expected=old.groups();require(initial.groups()==expected);
  for(int allowance:{0,1,4,8,16}){
   auto u=prepare<CurrentDUF>(joined);std::vector<int> before;for(int k:keys)before.push_back(u.data(k));auto owned=live;bool caught=false;budget=allowance;
   try{auto result=u.groups();require(result==expected);}catch(const std::bad_alloc&){caught=true;++failures;}budget=-1;
   require(live==owned&&u.node_count()==8&&u.component_count()==(joined?1u:8u));
   if(caught){for(std::size_t i=0;i<keys.size();++i)require(u.data(keys[i])==before[i]);}
   else if(joined){for(std::size_t i=0;i<keys.size();++i)require(u.data(keys[i])==(i==3?-8:keys[3]));}
   for(int k:keys)require(u.find(k)==(joined?keys[3]:k)&&u.size(k)==(joined?8:1));
  }
 }
 auto u=prepare<CurrentDUF>(true);auto expected=std::vector<std::vector<int>>{keys};require(u.groups()==expected&&u.data(keys[3])==-8);
 auto copy=u;copy.add(123);require(!u.contains(123)&&copy.component_count()==2);copy.unite(keys[3],123);expected[0].push_back(123);require(copy.groups()==expected&&copy.data(keys[3])==-9&&u.data(keys[3])==-8);
 CurrentDUF moved(std::move(copy));require(copy.empty()&&copy.groups().empty()&&moved.groups()==expected);copy.add(-2);require(copy.groups()==std::vector<std::vector<int>>{{-2}}&&copy.data(-2)==-1);
 auto output=u.groups();output[0][0]=999;require(u.groups()==std::vector<std::vector<int>>{keys});
 auto future=prepare<CurrentDUF>(true);(void)future.groups();
 for(int i=0;i<9;++i)future.add(1000+i);for(int i=1;i<9;++i)future.unite(1000,1000+i);future.unite(1000,keys[3]);
 for(int key:keys)require(future.find(key)==1000&&future.size(key)==17);
 require(future.data(1000)==-17);auto order=keys;for(int i=0;i<9;++i)order.push_back(1000+i);require(future.groups()==std::vector<std::vector<int>>{order});

}
int main(){auto start=live;run();require(live==start);std::cout<<"PASS checks="<<checks<<" allocation_failures="<<failures<<" live_delta=0\n";}

